const express = require('express');
const NodeCache = require('node-cache');
const axios = require('axios');

const app = express();
const responseCache = new NodeCache({ stdTTL: 300, checkperiod: 60 });

// Middleware to normalize request headers
app.use((req, res, next) => {
  req.normalizedHost = req.headers['x-forwarded-host'] || req.headers['host'] || 'default';
  next();
});

// Cache key generation - uses Host header for multi-tenant routing
function generateCacheKey(req) {
  const path = req.path.toLowerCase();
  const host = req.normalizedHost.toLowerCase();
  const variant = req.headers['x-cache-variant'] || 'default';
  return `${host}:${path}:${variant}`;
}

// Fetch upstream content
async function fetchUpstream(req) {
  const upstreamUrl = `http://internal-api.service.local${req.path}`;
  try {
    const response = await axios.get(upstreamUrl, {
      headers: {
        'X-Original-Host': req.normalizedHost,
        'X-Request-ID': req.headers['x-request-id'] || 'none'
      },
      timeout: 5000
    });
    return response.data;
  } catch (err) {
    return { error: 'upstream_unavailable', status: 502 };
  }
}

// Main content endpoint with caching
app.get('/api/content/*', async (req, res) => {
  const cacheKey = generateCacheKey(req);

  // Check cache first
  const cached = responseCache.get(cacheKey);
  if (cached) {
    res.set('X-Cache', 'HIT');
    res.set('X-Cache-Key', cacheKey);
    return res.json(cached);
  }

  // Fetch from upstream
  const data = await fetchUpstream(req);

  // Cache the response - unkeyed header x-cache-variant allows poisoning
  // The rendered content includes the host header value
  const responseBody = {
    content: data,
    meta: {
      served_for: req.normalizedHost,
      generated_at: new Date().toISOString(),
      cache_key: cacheKey
    }
  };

  // Store in cache with TTL
  if (!data.error) {
    responseCache.set(cacheKey, responseBody);
  }

  res.set('X-Cache', 'MISS');
  res.json(responseBody);
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'healthy', cache_stats: responseCache.getStats() });
});

// Cache management endpoint
app.post('/admin/cache/flush', (req, res) => {
  const authToken = req.headers['x-admin-token'];
  if (authToken !== process.env.ADMIN_TOKEN) {
    return res.status(403).json({ error: 'forbidden' });
  }
  responseCache.flushAll();
  res.json({ flushed: true });
});

// Serve dynamic configuration based on host
app.get('/config', (req, res) => {
  const cacheKey = `config:${req.normalizedHost}`;
  const cached = responseCache.get(cacheKey);
  if (cached) {
    return res.json(cached);
  }

  const config = {
    cdn_base: `https://${req.normalizedHost}/static`,
    api_base: `https://${req.normalizedHost}/api`,
    ws_endpoint: `wss://${req.normalizedHost}/ws`
  };

  responseCache.set(cacheKey, config);
  res.json(config);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Cache service listening on port ${PORT}`);
});
